/**
 * SEMANTIC-CATEGORY CENSUS
 * ========================
 *
 * The line-shape census (census.ts) shows a LONG TAIL: the top 30 normalised
 * line shapes are only ~37% of generated bytes and the largest single shape is
 * ~3.9%. That rules out "one repeated block is the size", so the useful question
 * is which MECHANISM the bytes belong to — several distinct line shapes can all
 * be the same emitter.
 *
 * Each line is charged to exactly one category, matched in priority order.
 */
import { join } from 'node:path'

const ROOT = join(import.meta.dirname, '..', '..')

const SPECS = [
  { id: 'example/json', module: '../../examples/json/parser.ts', exportName: 'jsonDoc' },
  { id: 'example/csv', module: '../../examples/csv/parser.ts', exportName: 'csvParser' },
  { id: 'example/graphql', module: '../../examples/graphql/parser.ts', exportName: 'graphqlDoc' },
  { id: 'example/css', module: '../../examples/css/parser.ts', exportName: 'Stylesheet' },
  { id: 'example/lang', module: '../../examples/lang/parser.ts', exportName: 'exprParser' },
  { id: 'example/jsonc', module: '../../examples/json/jsonc.ts', exportName: 'jsoncValue' },
  { id: 'example/jsonl', module: '../../examples/json/jsonl.ts', exportName: 'jsonl' },
]

/** Priority-ordered. First match wins, so put specific before general. */
const CATEGORIES: [string, RegExp][] = [
  ['rollback/restore', /\.length !== _(mk|fc|cme|sne)|\.length = _(mk|fc|cme)|_ctx\._(cstChildren|cstLeaves|cstRawChildren|cstTriviaLog|triviaLog|errors) = _(sc|sl|sr|stl|se)\d/],
  ['rollback markers', /const _(mk|mklg|mktl|fcl|fcr|fctl|cme)\w*\d* = /],
  ['trivia skip', /_tf\d+\(input|_sne\d+ = |_sea\d+ = |_tlg\d+/],
  ['leaf capture', /_cstLeaves \|\| _ctx\._cstRawChildren|const _lf\d+ = \{ _tag: 'leaf'|_cstLeaves\.push\(_lf|_cstRawChildren\.push\(_lf/],
  ['CST frame save/install', /_ctx\._cstChildren = |const _sc\d+ = _ctx\._cstChildren|_ctx\.captureTrivia = /],
  ['fail record', /_ctx\._fe = |_ctx\._fx = |const _fx\d+ = \[|_recordFail|_ctx\._errors/],
  ['first-set guard', /codePointAt\(.*\) \?\? -1|_ngc\d+|_gc\d+ >= |const _cc\d+ = /],
  ['terminal match', /charCodeAt|input\.slice|\.lastIndex|_re\d+\.exec|startsWith/],
  ['node build', /_build\[\d+\]\(|_tag: 'node'|_nd\d+ = |_rawEntry\(/],
  ['fields', /_fields|_fa\d+|_fe\d+\.name/],
  ['control flow', /^\s*(break|continue|return|if|else|while|for|do|switch|case|default|\{|\}|_lbl\d+:|_pfail:)/],
  ['fn decl', /^\s*(function|const _pf\d+ = |export const)/],
  ['var decl', /^\s*(const|let|var) /],
]

const { compile } = (await import(join(ROOT, 'src', 'index.ts'))) as { compile: (c: unknown) => { source: string } }

const totals = new Map<string, { bytes: number; lines: number }>()
const perFixtureCat = new Map<string, Map<string, number>>()
let grand = 0

for (const spec of SPECS) {
  const mod = (await import(join(import.meta.dirname, spec.module))) as Record<string, unknown>
  const gen = compile(mod[spec.exportName]).source
  const fx = new Map<string, number>()
  perFixtureCat.set(spec.id, fx)
  for (const line of gen.split('\n')) {
    const b = Buffer.byteLength(line) + 1
    grand += b
    let cat = 'other'
    for (const [name, re] of CATEGORIES) {
      if (re.test(line)) { cat = name; break }
    }
    const e = totals.get(cat) ?? { bytes: 0, lines: 0 }
    e.bytes += b; e.lines++
    totals.set(cat, e)
    fx.set(cat, (fx.get(cat) ?? 0) + b)
  }
}

const ranked = [...totals.entries()].sort((a, b) => b[1].bytes - a[1].bytes)
console.log('\nBYTES BY MECHANISM (all 7 example fixtures, ' + grand + ' B total)')
console.log('  ' + 'category'.padEnd(24) + 'bytes'.padStart(9) + 'pct'.padStart(7) + 'lines'.padStart(8))
let cum = 0
for (const [cat, e] of ranked) {
  cum += e.bytes
  console.log('  ' + cat.padEnd(24) + String(e.bytes).padStart(9) + (100 * e.bytes / grand).toFixed(2).padStart(7) + String(e.lines).padStart(8))
}
console.log('  ' + 'TOTAL'.padEnd(24) + String(cum).padStart(9))

console.log('\nexample/css ONLY (the 26.7x worst case)')
const css = perFixtureCat.get('example/css')!
const cssTotal = [...css.values()].reduce((a, b) => a + b, 0)
for (const [cat, b] of [...css.entries()].sort((x, y) => y[1] - x[1])) {
  console.log('  ' + cat.padEnd(24) + String(b).padStart(9) + (100 * b / cssTotal).toFixed(2).padStart(7))
}
